using Setak.IMS.DAL.Data;

namespace Setak.IMS.Services.Services
{
    public interface IEquipmentOutFieldService : IService, IRolePolicyFilter
    {
        Task CreateEquipmentOutFieldAsync(EquipmentOutFieldDto dto);
        Task DeleteEquipmentOutFieldAsync(int id);
        Task<EquipmentOutFieldDto?> GetEquipmentOutFieldByIdAsync(int id);
        Task<IEnumerable<EquipmentOutFieldDto>> EquipmentOutFieldListAsync();
        Task UpdateEquipmentOutFieldAsync(EquipmentOutFieldDto dto);
    }

    public class EquipmentOutFieldService(
        IRolePolicyFilterService rolePolicyFilterService,
        ILogger<EquipmentOutFieldService> logger,
        IMapper mapper,
        ApplicationDbContext dbContext
    ) : AbstractService<EquipmentOutFieldService>, IEquipmentOutFieldService
    {
        private readonly DbSet<EquipmentOutField> _dbSet = dbContext.Set<EquipmentOutField>();
<|editable_region_end|>


        public async Task CreateEquipmentOutFieldAsync(EquipmentOutFieldDto dto)
        {
            var entity = mapper.Map<EquipmentOutField>(dto);
            await _dbSet.AddAsync(entity);
            await dbContext.SaveChangesAsync();
        }

        public async Task DeleteEquipmentOutFieldAsync(int id)
        {
            var entity = await _dbSet.FindAsync(id);
            if (entity != null)
            {
                _dbSet.Remove(entity);
                await dbContext.SaveChangesAsync();
            }
        }

        public async Task<EquipmentOutFieldDto?> GetEquipmentOutFieldByIdAsync(int id)
        {
            var entity = await _dbSet.AsNoTracking().FirstOrDefaultAsync(e => e.Id == id);
            return entity != null ? mapper.Map<EquipmentOutFieldDto>(entity) : null;
        }

        public async Task<IEnumerable<EquipmentOutFieldDto>> EquipmentOutFieldListAsync()
        {
            var entities = await _dbSet.AsNoTracking().ToListAsync();
            return mapper.Map<IEnumerable<EquipmentOutFieldDto>>(entities);
        }

        public async Task UpdateEquipmentOutFieldAsync(EquipmentOutFieldDto dto)
        {
            var entity = await _dbSet.FindAsync(dto.Id);
            if (entity != null)
            {
                mapper.Map(dto, entity);
                _dbSet.Update(entity);
                await dbContext.SaveChangesAsync();
            }
        }
    }
}
